// Session-cached full library - makes back-nav to home instant, expires in 5 min.
const GAMES_CACHE_KEY = "ugp:games:v1";
const GAMES_CACHE_TTL = 5 * 60 * 1000;
export const listGamesCached = async () => {
  try {
    const raw = sessionStorage.getItem(GAMES_CACHE_KEY);
    if (raw) {
      const { ts, data } = JSON.parse(raw);
      if (Date.now() - ts < GAMES_CACHE_TTL && Array.isArray(data)) return data;
    }
  } catch { /* ignore corrupt cache */ }
  const data = await listGames();
  try {
    sessionStorage.setItem(GAMES_CACHE_KEY, JSON.stringify({ ts: Date.now(), data }));
  } catch { /* quota / private mode */ }
  return data;
};
export const invalidateGamesCache = () => {
  try { sessionStorage.removeItem(GAMES_CACHE_KEY); } catch { /* ignore */ }
};
export const prefetchGameEmbed = (slug) => {
  try {
    const link = document.createElement("link");
    link.rel = "prefetch";
    link.as = "document";
    link.href = gameEmbedUrl(slug);
    document.head.appendChild(link);
    setTimeout(() => link.remove(), 15000);
  } catch { /* ignore */ }
};
export const getGame = async (slug) => {
  if (STATIC_FIREBASE) return getGameStatic(slug);
  return (await api.get(`/games/${slug}`)).data;
};
export const gameEmbedUrl = (slug) => {
  if (STATIC_FIREBASE) return staticGameEmbedUrl(slug);
  return `${API_BASE}/games/${slug}/embed`;
};
export const pageEmbedUrl = (pageKey) => {
  if (STATIC_FIREBASE) {
    return `/page-embed.html?page=${encodeURIComponent(pageKey)}&t=${encodeURIComponent(pageKey)}`;
  }
  return `${API_BASE}/pages/${pageKey}/embed?t=${pageKey}`;
};

