// --- Owner: Games ---
export const ownerCreateGame = async (name, html) => {
  if (STATIC_FIREBASE) {
    throw makeApiError(400, "Packaged games require a new deploy to add or edit.");
  }
  const { data } = await api.post("/owner/games", { name, html });
  invalidateGamesCache();
  return data;
};
export const ownerUpdateGame = async (slug, name, html) => {
  if (STATIC_FIREBASE) {
    throw makeApiError(400, "Packaged games require a new deploy to add or edit.");
  }
  const { data } = await api.put(`/owner/games/${slug}`, { name, html });
  invalidateGamesCache();
  return data;
};
export const ownerDeleteGame = async (slug) => {
  if (STATIC_FIREBASE) {
    throw makeApiError(400, "Packaged games require a new deploy to remove.");
  }
  const { data } = await api.delete(`/owner/games/${slug}`);
  invalidateGamesCache();
  return data;
};
export const ownerImportBackup = async (file) => {
  if (STATIC_FIREBASE) return ownerImportBackupStatic(file);
  const body = new FormData();
  body.append("file", file);
  const { data } = await api.post("/owner/import-backup", body, {
    timeout: 10 * 60 * 1000,
  });
  invalidateGamesCache();
  return data;
};
